SELECT cr.cr_returning_customer_sk, cd_ret.cd_gender AS returning_gender, cd_ret.cd_marital_status AS returning_marital_status, hd_ret.hd_vehicle_count AS returning_vehicle_count, SUM(cr.cr_refunded_cash) AS total_refunded_cash, SUM(cr.cr_return_amt_inc_tax) AS total_return_inc_tax, COUNT(*) AS num_returns, ROW_NUMBER() OVER (PARTITION BY cd_ret.cd_gender ORDER BY SUM(cr.cr_refunded_cash) DESC) AS gender_rank, PERCENT_RANK() OVER (ORDER BY SUM(cr.cr_refunded_cash) DESC) AS overall_percentile, CASE WHEN SUM(cr.cr_refunded_cash) > 5000 THEN 'VIP' WHEN SUM(cr.cr_refunded_cash) BETWEEN 2000 AND 5000 THEN 'Gold' ELSE 'Silver' END AS customer_tier FROM catalog_returns cr JOIN customer_demographics cd_ret ON cr.cr_returning_cdemo_sk = cd_ret.cd_demo_sk JOIN household_demographics hd_ret ON cr.cr_returning_hdemo_sk = hd_ret.hd_demo_sk GROUP BY cr.cr_returning_customer_sk, cd_ret.cd_gender, cd_ret.cd_marital_status, hd_ret.hd_vehicle_count HAVING SUM(cr.cr_refunded_cash) > 0 ORDER BY total_refunded_cash DESC LIMIT 20
